text:
{
  "questions": [
    {
      "question_id": "q1",
      "question": "For each stream, how far is the measurement point from where an analyzer could stand?"
    },
    {
      "question_id": "q2",
      "question": "Do you already have numerical acceptance criteria, such as required accuracy or detection limits, for each stream?"
    },
    {
      "question_id": "q3",
      "question": "Over what range must each relevant target variable be monitored in each stream?"
    },
    {
      "question_id": "q4",
      "question": "How quickly must a result be available for each stream?"
    },
    {
      "question_id": "q5",
      "question": "Where could a probe be installed for each stream?"
    },
    {
      "question_id": "q6",
      "question": "Is either measurement point hot, under pressure or prone to build-up?"
    }
  ],
  "plan": {
    "objective": "Test whether the candidate NIR interfaces can support composition monitoring in each stream against client-agreed pilot criteria.",
    "samples_and_states": [
      {
        "text": "Collect representative whey and milk-concentrate samples across the client-agreed composition ranges and relevant physical states.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "reference_measurements": [
      {
        "text": "Pair spectra with time-aligned laboratory protein and fat results wherever those variables are relevant.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "setup": [
      {
        "text": "Acquire NIR spectra with the candidate interfaces on matched samples under controlled conditions before testing realistic process conditions.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "comparison": [
      {
        "text": "Compare interface-specific chemometric models within each stream for composition error, bias and sensitivity to physical-state changes.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "validation": [
      {
        "text": "Validate each model against laboratory results on independent production material excluded from model fitting and selection.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "go_no_go": [
      {
        "text": "Proceed only if validation meets the acceptance criteria agreed before testing and the tested interface suits the intended installation.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "not_demonstrated": [
      {
        "text": "Performance for untested compositions, physical states or installation conditions remains unknown.",
        "claim_type": "UNKNOWN",
        "evidence_ids": []
      }
    ],
    "steps": [
      "Clarify ranges, acceptance criteria and installation constraints.",
      "Collect representative samples across agreed compositions and physical states.",
      "Obtain time-aligned laboratory references for relevant variables.",
      "Set up interfaces and compare spectra and models within each stream.",
      "Validate using independent production material.",
      "Decide go or no-go against pre-agreed criteria."
    ]
  },
  "decision_basis": [
    {
      "text": "Base the interface decision for each stream on comparison with laboratory references on independent material against criteria agreed with the client before testing.",
      "claim_type": "PROPOSAL",
      "evidence_ids": []
    }
  ]
}
